93	function loadRegistry(regPath) {
94	  let raw;
95	  try {
96	    if (!lstatSync(regPath).isFile()) {
97	      return { ok: false, reason: 'registry not a regular file' };
98	    }
99	    raw = readFileSync(regPath);
100	  } catch (e) {
101	    return { ok: false, reason: `registry unreadable: ${e.code || 'EIO'}` };
102	  }
103	  let doc;
104	  try {
105	    doc = JSON.parse(raw.toString('utf8'));
106	  } catch {
107	    return { ok: false, reason: 'registry not valid JSON' };
108	  }
109	  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
110	    return { ok: false, reason: 'registry not an object' };
111	  }
112	  if (doc.version !== 2) {
113	    return { ok: false, reason: `registry version ${JSON.stringify(doc.version)} !== 2 (want the v2 lstat semantics)` };
114	  }
115	  if (!Array.isArray(doc.covered)) {
116	    return { ok: false, reason: 'registry covered not an array' };
117	  }
118	  const seen = new Set();
119	  for (const p of doc.covered) {
120	    if (typeof p !== 'string' || !COVERED_RE.test(p)) {
121	      return { ok: false, reason: `covered entry malformed: ${JSON.stringify(p)}` };
122	    }
123	    if (seen.has(p)) {
124	      return { ok: false, reason: `covered entry duplicated: ${JSON.stringify(p)}` };
125	    }
126	    seen.add(p);
127	  }
128	  return { ok: true, covered: doc.covered };
129	}
