132	function loadRows(readmePath) {
133	  let raw;
134	  try {
135	    if (!lstatSync(readmePath).isFile()) {
136	      return { ok: false, reason: 'README not a regular file' };
137	    }
138	    raw = readFileSync(readmePath, 'utf8');
139	  } catch (e) {
140	    return { ok: false, reason: `README unreadable: ${e.code || 'EIO'}` };
141	  }
142	  const rows = [];
143	  const bad = [];
144	  for (const line0 of raw.split('\n')) {
145	    const line = line0.replace(/^ {0,3}/, '');
146	    if (!line.startsWith('|')) continue;
147	    const m = line.match(/^\|\s*`((?:knowledge|lessons)\/[^`]+)`\s*\|/);
148	    if (m) { rows.push(m[1]); continue; }
149	    const firstCell = line.split('|')[1];
150	    if (firstCell && /^\s*`?(knowledge|lessons)\//.test(firstCell)) {
151	      bad.push(`format-unmapped:${firstCell.trim().slice(0, 80)}`);
152	    }
153	  }
154	  return { ok: true, rows, bad };
155	}
156	
157	function loadFiles(dirs) {
158	  const files = [];
159	  for (const d of dirs) {
160	    const base = basename(d);
161	    if (base !== 'knowledge' && base !== 'lessons') {
162	      return { ok: false, reason: `corpus dir outside the covered namespace (want knowledge|lessons): ${d}` };
163	    }
164	    let names;
165	    try {
166	      if (!lstatSync(d).isDirectory()) {
167	        return { ok: false, reason: `corpus dir not a directory: ${d}` };
168	      }
169	      names = readdirSync(d);
170	    } catch (e) {
171	      return { ok: false, reason: `corpus dir unreadable: ${d} (${e.code || 'EIO'})` };
172	    }
173	    for (const n of names) if (n.endsWith('.md')) files.push(`${base}/${n}`);
174	  }
175	  if (files.length === 0) {
176	    return { ok: false, reason: `no *.md under ${dirs.join(' + ')} (empty corpus)` };
177	  }
178	  return { ok: true, files: files.sort() };
179	}
180	
181	function evaluate(registryPath, readmePath, dirs) {
182	  const reg = loadRegistry(registryPath);
183	  if (!reg.ok) return { verdict: 'FAIL-CLOSED', reason: reg.reason, exit: 2 };
184	  const rd = loadRows(readmePath);
185	  if (!rd.ok) return { verdict: 'FAIL-CLOSED', reason: rd.reason, exit: 2 };
186	  const cf = loadFiles(dirs);
187	  if (!cf.ok) return { verdict: 'FAIL-CLOSED', reason: cf.reason, exit: 2 };
188	
189	  const fileSet = new Set(cf.files);
190	  const bad = [...rd.bad];
191	  const seen = new Map();
192	  for (const r of rd.rows) {
193	    if (seen.has(r)) {
194	      bad.push(`duplicate-row:${r}`);
195	    } else {
196	      seen.set(r, true);
197	      if (!fileSet.has(r)) bad.push(`orphan-row:${r}`);
198	    }
199	  }
200	  const rowSet = new Set(rd.rows);
201	  for (const f of cf.files) {
202	    if (!rowSet.has(f)) bad.push(`uncovered:${f}`);
203	  }
204	  const covered = new Set(reg.covered);
205	  const dirFor = {};
206	  for (const d of dirs) dirFor[basename(d)] = d;
207	  for (const c of reg.covered) {
208	    if (!fileSet.has(c)) {
209	      bad.push(`stale-covered:${c}`);
210	      continue;
211	    }
212	    // v2 (R57-V3): a covered member is scored by name only no longer — it
213	    // must lstat as a regular file in its namespace dir.
214	    const [ns, leaf] = [c.slice(0, c.indexOf('/')), c.slice(c.indexOf('/') + 1)];
215	    let lst;
216	    try {
217	      lst = lstatSync(join(dirFor[ns], leaf));
218	    } catch {
219	      bad.push(`stale-covered:${c}`);
220	      continue;
221	    }
222	    if (lst.isSymbolicLink()) {
223	      try {
224	        statSync(full);
225	        bad.push(`covered-not-file:${c}`);
226	      } catch {
227	        bad.push(`stale-covered:${c}`);
228	      }
229	      continue;
230	    }
231	    if (!lst.isFile()) {
232	      bad.push(`covered-not-file:${c}`);
233	    }
234	  }
235	  for (const f of cf.files) {
236	    if (!covered.has(f)) bad.push(`unpinned:${f}`);
237	  }
238	  const stats = { files: cf.files.length, rows: rd.rows.length, covered: reg.covered.length };
239	  if (bad.length > 0) return { verdict: 'DRIFT', ...stats, bad, exit: 1 };
240	  return { verdict: 'CLEAN', ...stats, exit: 0 };
241	}
242	
243	function emit(result) {
244	  if (result.verdict === 'CLEAN') {
245	    process.stdout.write(`README_MAP: CLEAN files=${result.files} rows=${result.rows} covered=${result.covered}\n`);
246	  } else if (result.verdict === 'DRIFT') {
247	    for (const b of result.bad.slice(1)) process.stdout.write(`README_MAP: note ${b}\n`);
248	    process.stdout.write(`README_MAP: DRIFT files=${result.files} rows=${result.rows} covered=${result.covered} bad=${result.bad.length} first=${result.bad[0]}\n`);
249	  } else {
250	    process.stdout.write(`README_MAP: FAIL-CLOSED reason=${result.reason}\n`);
251	  }
252	  process.exit(result.exit);
253	}
