255	function selftest() {
256	  const root = mkdtempSync(join(tmpdir(), 'readme-map-st.'));
257	  const results = [];
258	  const pass = (name, ok, detail) => {
259	    results.push({ name, ok });
260	    process.stdout.write(`case ${name}: ${ok ? 'PASS' : `FAIL ${detail || ''}`}\n`);
261	  };
262	  const run = (args, opts = {}) => spawnSync(process.execPath, [SELF, ...args],
263	    { encoding: 'utf8', timeout: 60_000, ...opts });
264	  const last = (r) => `${r.stdout || ''}`.trim().split('\n').pop() || '';
265	  const mkdirp = (d) => { rmSync(d, { recursive: true, force: true }); mkdirSync(d, { recursive: true }); };
266	  const fixture = (dir, { files = ['knowledge/a.md', 'lessons/b.md'], dirs = [], links = [], rows, covered } = {}) => {
267	    mkdirp(dir);
268	    mkdirp(join(dir, 'corpus')); mkdirp(join(dir, 'corpus/knowledge')); mkdirp(join(dir, 'corpus/lessons'));
269	    for (const f of files) writeFileSync(join(dir, 'corpus', f), `# ${f}\n`);
270	    for (const d of dirs) mkdirp(join(dir, 'corpus', d));
271	    for (const l of links) symlinkSync(join(dir, 'corpus', `${l}.no-such-target`), join(dir, 'corpus', l));
272	    const rowText = rows !== undefined ? rows : files.map((f) => `| \`${f}\` | desc | ptr |\n`).join('');
273	    writeFileSync(join(dir, 'corpus/README.md'), `# README\n\n## Coverage map\n\n${rowText}`);
274	    writeFileSync(join(dir, 'reg.json'), JSON.stringify({ version: 2, covered: covered !== undefined ? covered : files }, null, 2));
275	    return { reg: join(dir, 'reg.json'), rm: join(dir, 'corpus/README.md'), kd: join(dir, 'corpus/knowledge'), ld: join(dir, 'corpus/lessons') };
276	  };
277	  const argsOf = (f) => ['--registry', f.reg, '--readme', f.rm, '--corpus', f.kd, '--corpus', f.ld];
278	
279	  try {
280	    // 1 — clean bimap
281	    {
282	      const f = fixture(join(root, 'd1'));
283	      const r = run(argsOf(f));
284	      pass('clean', r.status === 0 && last(r) === 'README_MAP: CLEAN files=2 rows=2 covered=2',
285	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
286	    }
287	    // 2 — uncovered: file without row
288	    {
289	      const f = fixture(join(root, 'd2'), { rows: '| `knowledge/a.md` | d | p |\n' });
290	      const r = run(argsOf(f));
291	      pass('uncovered', r.status === 1 && `${r.stdout}`.includes('uncovered:lessons/b.md'),
292	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
293	    }
294	    // 3 — orphan-row: row without file
295	    {
296	      const f = fixture(join(root, 'd3'), { rows: '| `knowledge/a.md` | d | p |\n| `lessons/b.md` | d | p |\n| `lessons/gone.md` | d | p |\n' });
297	      const r = run(argsOf(f));
298	      pass('orphan-row', r.status === 1 && `${r.stdout}`.includes('orphan-row:lessons/gone.md'),
299	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
300	    }
301	    // 4 — duplicate-row
302	    {
303	      const f = fixture(join(root, 'd4'), { rows: '| `knowledge/a.md` | d | p |\n| `knowledge/a.md` | d2 | p2 |\n| `lessons/b.md` | d | p |\n' });
304	      const r = run(argsOf(f));
305	      pass('duplicate-row', r.status === 1 && `${r.stdout}`.includes('duplicate-row:knowledge/a.md'),
306	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
307	    }
308	    // 5 — format-unmapped: corpus-shaped first cell, not a clean row
309	    {
310	      const f = fixture(join(root, 'd5'), { rows: '| `knowledge/a.md` | d | p |\n| `lessons/b.md` | d | p |\n| knowledge/stray.md | d | p |\n' });
311	      const r = run(argsOf(f));
312	      pass('format-unmapped', r.status === 1 && `${r.stdout}`.includes('format-unmapped:'),
313	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
314	    }
315	    // 6 — stale-covered: covered entry whose file is gone (orphan too)
316	    {
317	      const f = fixture(join(root, 'd6'), { covered: ['knowledge/a.md', 'lessons/b.md', 'lessons/gone.md'] });
318	      const r = run(argsOf(f));
319	      pass('stale-covered', r.status === 1 && `${r.stdout}`.includes('stale-covered:lessons/gone.md'),
320	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
321	    }
322	    // 7 — unpinned: live file absent from covered
323	    {
324	      const f = fixture(join(root, 'd7'), { covered: ['knowledge/a.md'] });
325	      const r = run(argsOf(f));
326	      pass('unpinned', r.status === 1 && `${r.stdout}`.includes('unpinned:lessons/b.md'),
327	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
328	    }
329	    // 8 — covered=[] while files remain: unpinned, never vacuous CLEAN
330	    {
331	      const f = fixture(join(root, 'd8'), { covered: [] });
332	      const r = run(argsOf(f));
333	      pass('empty-covered', r.status === 1 && `${r.stdout}`.includes('unpinned:'),
334	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-160))}`);
335	    }
336	    // 9 — malformed registry JSON: FAIL-CLOSED exit 2
337	    {
338	      const f = fixture(join(root, 'd9'));
339	      writeFileSync(f.reg, '{ not json');
340	      const r = run(argsOf(f));
341	      pass('malformed-registry', r.status === 2, `exit=${r.status}`);
342	    }
343	    // 10 — registry version 1 (the superseded v1 registry): FAIL-CLOSED
344	    {
345	      const f = fixture(join(root, 'd10'));
346	      writeFileSync(f.reg, JSON.stringify({ version: 1, covered: [] }));
347	      const r = run(argsOf(f));
348	      pass('registry-version', r.status === 2, `exit=${r.status}`);
349	    }
350	    // 11 — covered entry outside knowledge|lessons: FAIL-CLOSED
351	    {
352	      const f = fixture(join(root, 'd11'), { covered: ['knowledge/a.md', 'lessons/b.md', 'scripts/x.md'] });
353	      const r = run(argsOf(f));
354	      pass('covered-scope', r.status === 2, `exit=${r.status}`);
355	    }
356	    // 12 — README removed: FAIL-CLOSED
357	    {
358	      const f = fixture(join(root, 'd12'));
359	      rmSync(f.rm);
360	      const r = run(argsOf(f));
361	      pass('readme-absent', r.status === 2, `exit=${r.status}`);
362	    }
363	    // 13 — corpus dir missing: FAIL-CLOSED
364	    {
365	      const f = fixture(join(root, 'd13'));
366	      rmSync(f.ld, { recursive: true, force: true });
367	      const r = run(argsOf(f));
368	      pass('corpus-dir-missing', r.status === 2, `exit=${r.status}`);
369	    }
370	    // 14 — non-corpus rows ignored (backticked other paths; prose rows)
371	    {
372	      const f = fixture(join(root, 'd14'), {
373	        rows: '| `knowledge/a.md` | d | `scripts/x.mjs` |\n| `lessons/b.md` | mentions `knowledge/other.md` inside | p |\n| `scripts/tool.mjs` | not corpus | p |\n',
374	      });
375	      const r = run(argsOf(f));
376	      pass('non-corpus-rows', r.status === 0 && last(r) === 'README_MAP: CLEAN files=2 rows=2 covered=2',
377	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
378	    }
379	    // 15 — v2 (R57-V3): a covered member naming a directory is DRIFT covered-not-file
380	    {
381	      const f = fixture(join(root, 'd15'), {
382	        files: ['knowledge/a.md', 'lessons/b.md'],
383	        dirs: ['knowledge/dir.md'],
384	        rows: '| `knowledge/a.md` | d | p |\n| `lessons/b.md` | d | p |\n| `knowledge/dir.md` | d | p |\n',
385	        covered: ['knowledge/a.md', 'lessons/b.md', 'knowledge/dir.md'],
386	      });
387	      const r = run(argsOf(f));
388	      pass('covered-not-file', r.status === 1 && `${r.stdout}`.includes('covered-not-file:knowledge/dir.md'),
389	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-200))}`);
390	    }
391	    // 16 — v2 (R57-V3): a covered member that is a dangling symlink is DRIFT stale-covered
392	    {
393	      const f = fixture(join(root, 'd16'), {
394	        files: ['knowledge/a.md', 'lessons/b.md'],
395	        links: ['lessons/link.md'],
396	        rows: '| `knowledge/a.md` | d | p |\n| `lessons/b.md` | d | p |\n| `lessons/link.md` | d | p |\n',
397	        covered: ['knowledge/a.md', 'lessons/b.md', 'lessons/link.md'],
398	      });
399	      const r = run(argsOf(f));
400	      pass('symlink-stale-covered', r.status === 1 && `${r.stdout}`.includes('stale-covered:lessons/link.md'),
401	        `exit=${r.status} out=${JSON.stringify(`${r.stdout}`.slice(-200))}`);
402	    }
403	  } finally {
404	    rmSync(root, { recursive: true, force: true });
405	  }
406	  const passed = results.filter((r) => r.ok).length;
407	  process.stdout.write(`README_MAP_SELFTEST: PASS (${passed}/${results.length})\n`);
408	  process.stdout.write(`VERDICT: ${passed === results.length ? 'PASS' : 'FAIL'}\n`);
409	  process.exit(passed === results.length ? 0 : 1);
410	}
411	
412	const argv = process.argv.slice(2);
413	if (argv.includes('--selftest')) selftest();
414	let registry = join(LANE, DEFAULT_REGISTRY);
415	let readme = join(LANE, DEFAULT_README);
416	const dirs = [];
417	for (let i = 0; i < argv.length; i++) {
418	  const a = argv[i];
419	  if (a === '--registry' && argv[i + 1]) registry = resolve(argv[++i]);
420	  else if (a === '--readme' && argv[i + 1]) readme = resolve(argv[++i]);
421	  else if (a === '--corpus' && argv[i + 1]) dirs.push(resolve(argv[++i]));
422	  else usage();
423	}
424	emit(evaluate(registry, readme, dirs.length ? dirs : DEFAULT_DIRS.map((d) => join(LANE, d))));
